import{U as e,W as t,nt as n,t as r}from"./chunks/framework.DRwsyrlO.js";import"./chunks/assets.DbQFHwAY.js";var i=JSON.parse(`{"title":"从岛屿工业到航天：资格、研究与飞船","description":"了解航天资格任务、工业材料与研究的联系，以及自造飞船、船锚和后续太空生活的准备事项。","frontmatter":{"title":"从岛屿工业到航天：资格、研究与飞船","description":"了解航天资格任务、工业材料与研究的联系，以及自造飞船、船锚和后续太空生活的准备事项。"},"headers":[],"relativePath":"skyblock/spaceflight.md","filePath":"skyblock/spaceflight.md"}`),a={name:`skyblock/spaceflight.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="从岛屿工业到航天-资格、研究与飞船" tabindex="-1">从岛屿工业到航天：资格、研究与飞船 <a class="header-anchor" href="#从岛屿工业到航天-资格、研究与飞船" aria-label="Permalink to “从岛屿工业到航天：资格、研究与飞船”">​</a></h1><p>想把工厂里做出的东西用在飞船上，可以先从任务与研究的连接看起。本页整理发展前提与关键区别，具体设备操作以匹配客户端内的指南和当前任务菜单为准。</p><div class="warning custom-block"><p class="custom-block-title">航行前先看毕业规则</p><p>成功从空岛迁移到太阳系太空会触发毕业，岛主毕业会注销原岛并影响队友。请先阅读 <a href="./graduation.html">离岛毕业规则</a>，不要把这趟航行当作随时可回岛的观光。</p></div><h2 id="资源和工业可以并行准备" tabindex="-1">资源和工业可以并行准备 <a class="header-anchor" href="#资源和工业可以并行准备" aria-label="Permalink to “资源和工业可以并行准备”">​</a></h2><p>早期的资源来自种植、任务、刷矿机与专用虚空钓鱼。五级刷矿机和按岛恢复的矿额共同影响矿物生产，先看 <a href="./resources.html">资源与额度说明</a>。</p><p>机械加工、电力、化工、仓储和自动合成可以按需要组合。Mekanism 的反物质丸与 HDPE 片等材料会进入航天资格或载人研究成本，工业发展因此与后面的研究有实际联系；不代表所有模组都必须逐个通关。</p><h2 id="dimensions" tabindex="-1">下界与末地需要任务解锁 <a class="header-anchor" href="#dimensions" aria-label="Permalink to “下界与末地需要任务解锁”">​</a></h2><p>当前任务配置中，<strong>猎杀者 II 解锁下界，猎杀者 IV 解锁末地并提供门框</strong>。先在任务菜单检查个人前置和统计要求：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is missions</span></span></code></pre></div><p>获得钻石物品不一定等于完成“开采钻石矿”等事件条件。探索任务也不等于每名成员第一次进入都会单独领奖，遇到统计差异时先核对任务说明。</p><h2 id="license" tabindex="-1">星海启航资格 <a class="header-anchor" href="#license" aria-label="Permalink to “星海启航资格”">​</a></h2><p>当前资格任务要求在首次屠龙后，<strong>手动提交反物质丸 1 枚</strong>，并满足个人前置与合法所属岛屿等条件。</p><table tabindex="0"><thead><tr><th>完成后</th><th>含义</th></tr></thead><tbody><tr><td>个人研究资格</td><td>取得继续相关航天研究的资格，研究本身仍有前置和材料成本</td></tr><tr><td>岛屿航天矿资源</td><td>为所属岛屿刷矿机加入七种航天矿，仍需结合生成器与资源规则发展</td></tr><tr><td>飞船与设备</td><td>不会自动赠送一艘飞船，需要自己研究、制造、建造与组装</td></tr></tbody></table><p>具体目标、交付入口与奖励以当前任务菜单为准。本页不提供管理员发放或绕过任务的命令。</p><h2 id="ship" tabindex="-1">亲手搭船，再准备航行 <a class="header-anchor" href="#ship" aria-label="Permalink to “亲手搭船，再准备航行”">​</a></h2><p>Interstellaris 提供航天研究、设备与航行系统，Sable 是其移动结构物理前置。它们支撑的是玩家搭建、组装和驾驶的方块飞船；第三方模组本体不属于 PotgCraft 自研内容。</p><figure class="campaign-photo space-photo"><img src="/images/skyblock/ship-landing.png" alt="玩家自造飞船在天体地表附近尝试着陆" width="1920" height="1080" loading="lazy"><figcaption>玩家自造飞船 · 尝试着陆</figcaption></figure><p>准备时逐项检查：</p><ol><li><strong>研究与材料</strong>：确认相关设备已解锁，准备船体与制造材料。</li><li><strong>船体与设备</strong>：驾驶舱、引擎和其他必要设施需符合当前组装要求。</li><li><strong>能源与推进剂</strong>：按实际引擎及设备要求准备，不把“船已组装”等同于“可以航行”。</li><li><strong>目的地与环境</strong>：确认航线、维度与环境装备，不是所有星图目标都有可登陆地表。</li><li><strong>随船机器</strong>：先核对兼容性，不保证任意模组设备都能无损带上船。</li><li><strong>离岛安排</strong>：确认同岛伙伴、乘员与需要保留的物资，完成 <a href="./graduation.html#checklist">出发检查</a>。</li></ol><p>客户端的组装按键、设备配方与航线操作尚需配套实测截图，本页不杜撰逐键教程。</p><h2 id="respawn" tabindex="-1">船锚与重生 <a class="header-anchor" href="#respawn" aria-label="Permalink to “船锚与重生”">​</a></h2><p>船上重生需要正确设置合法船锚，并满足绑定、维度等要求。<strong>造好飞船不等于默认能在船上复活。</strong> 离岛前应确认当前重生路线；没有核实前不要通过死亡测试重要资产。</p><p>科技空岛基础死亡保护为有限 <strong>3 次</strong>，实际效果受个人开关和剩余次数影响，耗尽后不再构成保护。它与增强生存的基础 10 次不同。</p><h2 id="空岛之外还能做什么" tabindex="-1">空岛之外还能做什么？ <a class="header-anchor" href="#空岛之外还能做什么" aria-label="Permalink to “空岛之外还能做什么？”">​</a></h2><p>可以继续探索有地表的天体、寻找外星材料，或建设 <a href="./stations.html">固定空间站</a>。当前火星自然钽铌矿脉只影响新生成区块，不代表已有区块会补矿，也不代表机器矿池候选已开放。</p><p>后期宇宙工程还包括在太阳系太空接收木卫一磁通环工程电力，需要对应工程进度、所有权和完整接收结构，不能当作刚离岛就有的免费能源。</p><p>资料依据：2026-11-20 内容交接。当前生产内容以 Interstellaris 0.6.3a 与空间站扩展 2.0.0 为核对基线；客户端按服主发布的匹配整合包安装。</p><p><a href="./resources.html">资源成长</a> · <a href="./graduation.html">毕业规则</a> · <a href="./stations.html">空间站核心</a></p>`,28)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};